<?php
use App\Http\Controllers\StoreController as C;
use Illuminate\Support\Facades\Route;
Route::get('/',[C::class,'home'])->name('home');Route::get('/menu',[C::class,'menu'])->name('menu');
Route::view('/login','auth.login')->name('login');Route::post('/login',[C::class,'login'])->name('login.submit');Route::view('/register','auth.register')->name('register');Route::post('/register',[C::class,'register'])->middleware('throttle:5,1')->name('register.submit');
Route::match(['get','post'],'/owner-setup',[C::class,'ownerSetup'])->middleware('throttle:3,10')->name('owner.setup');
Route::view('/reservation','reservation')->name('reservation');Route::post('/reservation',[C::class,'placeReservation'])->middleware('throttle:5,1')->name('reservation.submit');
Route::middleware(['auth','active'])->group(function(){Route::post('/logout',[C::class,'logout'])->name('logout');Route::get('/dashboard',[C::class,'dashboard'])->name('dashboard');Route::get('/account',[C::class,'account'])->name('account');Route::get('/orders/{order}',[C::class,'showOrder'])->name('orders.show');Route::post('/orders',[C::class,'checkout'])->name('checkout');Route::post('/orders/{order}/payment',[C::class,'submitPayment'])->name('payments.submit');Route::get('/payment-evidence/{payment}',[C::class,'paymentEvidence'])->name('payments.evidence');});
Route::post('/cart/{product}',[C::class,'addCart'])->name('cart.add');Route::get('/cart',[C::class,'cart'])->name('cart');
Route::prefix('manage')->middleware(['auth','role:super_admin,admin'])->group(function(){Route::get('/orders',[C::class,'adminOrders'])->name('manage.orders');Route::patch('/orders/{order}',[C::class,'updateOrder'])->name('manage.orders.update');Route::get('/payments',[C::class,'paymentReviews'])->name('manage.payments');Route::post('/payments/{payment}',[C::class,'reviewPayment'])->name('manage.payments.review');Route::get('/payment-evidence/{payment}',[C::class,'paymentEvidence'])->name('manage.payments.evidence');Route::get('/reservations',[C::class,'reservations'])->name('manage.reservations');Route::patch('/reservations/{reservation}',[C::class,'reviewReservation'])->name('manage.reservations.review');Route::get('/categories',[C::class,'categories'])->name('manage.categories');Route::post('/categories',[C::class,'saveCategory'])->name('manage.categories.save');Route::get('/products',[C::class,'products'])->name('manage.products');Route::post('/products',[C::class,'saveProduct'])->name('manage.products.save');Route::get('/customers',[C::class,'customers'])->name('manage.customers');Route::patch('/customers/{user}/active',[C::class,'setActive'])->name('manage.customers.active');Route::get('/reports',[C::class,'report'])->name('manage.reports');Route::get('/audit',[C::class,'auditLogs'])->middleware('role:super_admin')->name('manage.audit');});
Route::prefix('staff')->middleware(['auth','role:super_admin,admin,staff'])->group(function(){Route::get('/orders',[C::class,'adminOrders'])->name('staff.orders');Route::patch('/orders/{order}',[C::class,'updateOrder'])->name('staff.orders.update');});
